def f(g):
    H,W=len(g),len(g[0]); out=[row[:] for row in g]
    # find regions of non-8: connected comps
    seen=[[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=8 and not seen[r][c]:
                st=[(r,c)]; reg=[]
                while st:
                    y,x=st.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; reg.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]!=8: st.append((ny,nx))
                rs=[y for y,_ in reg]; cs=[x for _,x in reg]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                # pattern bbox: nonzero color cells (any nonzero !=8) within region
                pts=[(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1) if g[y][x]!=0 and g[y][x]!=8]
                if not pts: continue
                py=[y for y,_ in pts]; px=[x for _,x in pts]
                p0,p1,q0,q1=min(py),max(py),min(px),max(px)
                P=[[g[y][x] for x in range(q0,q1+1)] for y in range(p0,p1+1)]
                ph,pw=p1-p0+1,q1-q0+1
                for y in range(r0,r1+1):
                    for x in range(c0,c1+1):
                        out[y][x]=P[(y-p0)%ph][(x-q0)%pw]
    return out
